      "achados": [
        {
          "proposicao": "O texto situa o licenciamento ambiental de petróleo offshore no Brasil como procedimento complexo por envolver responsabilidades legais em níveis federal, estadual e municipal.",
          "trechos": [
            "Efb512861b5596815:0:698"
          ],
          "condicoes": [
            "aplicado ao contexto descrito de atividades offshore de exploração e produção de petróleo"
          ],
          "limites": [
            "não detalha critérios de repartição de competência entre os entes",
            "não apresenta condicionantes, monitoramento ou controles operacionais específicos"
          ]
        },
        {
          "proposicao": "O texto atribui ao IBAMA a condução do licenciamento ambiental federal no Brasil e apresenta uma resolução do CONAMA como norma geral aplicável ao licenciamento ambiental do petróleo.",
          "trechos": [
            "Efb512861b5596815:0:698",
            "Efb512861b5596815:1398:2091"
